// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.Map;

import org.eclipse.rdf4j.common.annotation.Experimental;

/**
 * The engine's specialization order over execution strategies, used to decide between candidates whose costs do not
 * separate.
 * <p>
 * <b>Why this exists.</b> Until now this order was expressed only as the physical position of {@code if} statements in
 * {@code LmdbNativeRowStep.openUnorderedInput} and {@code LmdbNativeGroupStep.evaluateAll} — whichever rung was written
 * first won. That is not a principle, it is an accident, and it is the direct cause of two measured 2x regressions: a
 * code-generating kernel rung was inserted above the batch and WCOJ rungs, so as soon as it learned to compile their
 * plan shapes it captured them by position alone. It is also why {@code LmdbNativeGroupStep.prefixRunHandlesRow} exists
 * — a hand-written guard encoding exactly one edge of this relation, added after a third regression of the same kind.
 * <p>
 * <b>The principle being encoded.</b> A strategy that reduces the <em>number of rows</em> enumerated (prefix runs walk
 * one index position per distinct value; a worst-case-optimal join is bounded well below the product of its inputs;
 * factorization sums its branches instead of multiplying them) is preferred over one that merely reduces the <em>cost
 * per row</em> (the compiled kernels). An algorithmic win survives a bad estimate; a constant-factor win does not. Cost
 * may still overrule this order, but only by strict domination — that is, only when it is certain.
 * <p>
 * <b>One qualification, from measurement.</b> Calibration (2026-07-26) showed the kernels are not <em>purely</em>
 * constant-factor reducers. The ceiling on operator fusion alone is 1.48x on an isolated cyclic shape, yet whole-query
 * kernel wins reach 5.71x; the gap means that on some shapes the kernel also does less work, through access paths the
 * interpreted chain does not take. The ordering below is still the right default — an uncertain estimate should not be
 * allowed to demote a guaranteed algorithmic bound — but it is a default, not a law, and the cost model is expected to
 * overrule it once the kernel can report its own row estimate rather than inheriting the interpreted plan's.
 * <p>
 * Making the order data rather than control flow has three consequences worth the file: selection becomes a function of
 * the candidate <em>set</em> rather than of evaluation order, which is testable by permuting the candidates; adding a
 * rung no longer silently re-ranks its neighbours; and the hand-written guards can be deleted in favour of one
 * declaration.
 */
@Experimental
final class LmdbNativeStrategyPreference {

	/**
	 * Most specialized first. Ties inside this list are impossible; strategies absent from it are less preferred than
	 * every strategy in it and are ranked against one another by the order they were offered.
	 * <p>
	 * Two orderings here are deliberately chosen to preserve today's behaviour exactly, so that routing the existing
	 * two-way arbitration sites through this table changes nothing: {@code batch} precedes {@code parallelPipelines}
	 * and {@code factorizedTail} precedes {@code parallelAggregation}, matching the existing tie-breaks in
	 * {@code LmdbNativeStrategyProposal.chooseTag} and {@code LmdbNativeGroupStep.evaluateParallelOrFactorized}, both
	 * of which keep the sequential strategy when the costs are equal.
	 */
	private static final String[] ORDER = {
			// Structural short-circuits: these answer the query from an index intersection outright.
			LmdbNativeAttemptMetrics.PATH_EXISTS_INTERSECTION,
			// Row-count reducers: one index position per distinct value.
			LmdbNativeAttemptMetrics.PATH_PREFIX_RUN_GROUPS,
			LmdbNativeAttemptMetrics.PATH_PREFIX_RUN,
			LmdbNativeAttemptMetrics.PATH_ORDERED_DISTINCT_GROUPS,
			LmdbNativeAttemptMetrics.PATH_ORDERED_DISTINCT,
			LmdbNativeAttemptMetrics.PATH_ORDERED_SINGLE_PATTERN_GROUPS,
			// Worst-case-optimal join: bounded below any pairwise plan on cyclic shapes.
			LmdbNativeAttemptMetrics.PATH_WCOJ,
			// Factorization: sums branches where a nested loop would multiply them.
			LmdbNativeAttemptMetrics.PATH_FACTORIZED_TAIL,
			LmdbNativeAttemptMetrics.PATH_FACTORIZED_ROWS,
			// Set-at-a-time execution over the same row count.
			LmdbNativeAttemptMetrics.PATH_BATCH,
			LmdbNativeAttemptMetrics.PATH_PARALLEL_AGGREGATION,
			LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES,
			LmdbNativeAttemptMetrics.PATH_CHUNK_PIPELINE,
			// Constant-factor reducers: same rows, cheaper per row.
			LmdbNativeAttemptMetrics.PATH_JANINO_AGGREGATE,
			LmdbNativeAttemptMetrics.PATH_JANINO_KERNEL,
			LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE,
			LmdbNativeAttemptMetrics.PATH_IR_KERNEL,
			// Last resorts.
			LmdbNativeAttemptMetrics.PATH_ADAPTIVE_FILTER_PLACEMENT,
			LmdbNativeAttemptMetrics.PATH_NESTED_LOOP,
	};

	private static final Map<String, Integer> RANKS = buildRanks();

	private LmdbNativeStrategyPreference() {
	}

	private static Map<String, Integer> buildRanks() {
		Map<String, Integer> ranks = new java.util.HashMap<>();
		for (int i = 0; i < ORDER.length; i++) {
			ranks.put(ORDER[i], i);
		}
		return Map.copyOf(ranks);
	}

	/**
	 * Specialization rank of a strategy tag: lower is more specialized. Unknown tags rank last, so an unrecognised
	 * strategy can never displace a declared one without proving it on cost.
	 * <p>
	 * Parameterized labels (for example {@code factorizedRows(flatPrefix=1, ...)}) are matched on the part before the
	 * opening parenthesis, because that is the form the explain layer emits.
	 */
	static int rank(String tag) {
		if (tag == null) {
			return Integer.MAX_VALUE;
		}
		Integer direct = RANKS.get(tag);
		if (direct != null) {
			return direct;
		}
		int paren = tag.indexOf('(');
		if (paren > 0) {
			Integer base = RANKS.get(tag.substring(0, paren));
			if (base != null) {
				return base;
			}
		}
		return Integer.MAX_VALUE;
	}

	/** True when {@code candidate} is strictly more specialized than {@code incumbent}. */
	static boolean prefers(String candidate, String incumbent) {
		int candidateRank = rank(candidate);
		int incumbentRank = rank(incumbent);
		return candidateRank != Integer.MAX_VALUE && candidateRank < incumbentRank;
	}
}
